/* Human-owned drafting record. Rule-based coaching is deliberately not labelled live AI. */
const Diplomacy=(()=>{
 const initial=[
  {id:'P1',kind:'Preamble',text:'Recognizing that equitable access requires both available vaccines and the capacity to deliver them, and that national circumstances differ,'},
  {id:'OP1',kind:'Member States',text:'URGES Member States to prioritize access according to health need and to prepare national delivery plans, including arrangements for underserved communities;'},
  {id:'OP2',kind:'Partners',text:'INVITES relevant partners to support transparent financing, predictable production and delivery capacity, in collaboration with national authorities;'},
  {id:'OP3',kind:'Director-General',text:'REQUESTS the Director-General to provide technical assistance upon request and report on implementation barriers to a subsequent Health Assembly.'}
 ];
 let record;const clone=x=>JSON.parse(JSON.stringify(x));
 function reset(){record={paragraphs:initial.map(p=>({...p,status:'open'})),events:[],contributions:[],reservations:[],implementation:{owner:'',deadline:'',indicator:''},committee:false,plenary:false};}
 function contribute(role,kind,text){text=String(text).trim();if(record.plenary)throw Error('The negotiation record is closed.');if(!['Kitala','Nordland','Meridia','Pelagia','Assembly Chair'].includes(role)||!['National statement','Question','Conditional offer','Response','Chair summary'].includes(kind))throw Error('Choose a participant role and contribution type.');if(text.length<20||text.length>1000)throw Error('Write 20–1000 characters so your contribution explains a position.');if(record.contributions.length>=40)throw Error('This session already has 40 recorded contributions. Include further discussion in your final reflection.');const entry={number:record.contributions.length+1,role,kind,text};record.contributions.push(entry);log('Student contribution',role+' recorded '+kind.toLowerCase()+' #'+entry.number+'.');return clone(entry);}
 function log(kind,text){record.events.push({number:record.events.length+1,kind,text:String(text).slice(0,2500)});}
 function edit(id,text,status,author){if(record.plenary)throw Error('The adopted text is locked. Start a new simulation to negotiate again.');const p=record.paragraphs.find(p=>p.id===id);text=String(text).trim();if(!p||text.length<20||text.length>1200||!['open','bracketed','agreed ad ref'].includes(status))throw Error('Use 20–1200 characters and a valid paragraph status.');if(p.text===text&&p.status===status)return;log('Paragraph revision',author+' | '+id+' | '+status+' | Previous: '+p.text+' | Revised: '+text);p.text=text;p.status=status;record.committee=false;}
 function ready(){return record.paragraphs.every(p=>p.status==='agreed ad ref');}
 function committee(){if(!ready())throw Error('Resolve every paragraph before the committee recommendation.');record.committee=true;log('Committee','No objection remains to the negotiated package and reviewed text. Recommendation sent to plenary.');}
 function invalidate(){if(record.committee){record.committee=false;log('Returned to consultation','Package revised; committee and plenary consideration must be repeated.');}record.plenary=false;}
 function adopt(){if(!record.committee||!ready())throw Error('A committee recommendation is required.');record.plenary=true;log('Plenary','Final no-objection check completed; simulated resolution adopted.');}
 function reservation(role,text){text=String(text).trim();if(!text||text.length>600)throw Error('Enter an explanation of position (maximum 600 characters).');if(record.plenary)throw Error('The record is closed.');record.reservations.push({role,text});log('Explanation of position',role+': '+text);}
 function implementation(owner,deadline,indicator){record.implementation={owner:String(owner).trim().slice(0,160),deadline:String(deadline).trim().slice(0,160),indicator:String(indicator).trim().slice(0,400)};}
 function snapshot(){return clone(record);}
 function reportSections(){return [
  {title:'Resolution status and authority',text:'Simulated Committee A recommendation followed by closing-plenary adoption without a vote. This educational resolution makes recommendations; the allocation and financing package is a separate fictional negotiated pledge annex, not a WHO power to command national resources.'},
  ...record.paragraphs.map(p=>({title:p.id+' - '+p.kind,text:p.text})),
  {title:'Student-authored participation',text:record.contributions.map(c=>c.number+'. '+c.role+' / '+c.kind+': '+c.text).join('\n')||'No original written contributions were recorded.'},
  {title:'Explanations of position',text:record.reservations.map(r=>r.role+': '+r.text).join('\n')||'No explanation of position recorded. An explanation does not by itself block consensus; an explicit objection does.'},
  {title:'Implementation responsibilities (student planning)',text:'Owner: '+(record.implementation.owner||'Not specified')+'. Timing: '+(record.implementation.deadline||'Not specified')+'. Indicator: '+(record.implementation.indicator||'Not specified')+'. These are follow-up planning notes, not additional adopted commitments.'},
  {title:'Human and automated participation',text:'Students controlled assigned roles and approved the negotiated wording. Unassigned delegates used authored numeric mandates. Coaching was rule-based, not generative AI. No live model made decisions or cast votes. Group work used one shared screen.'},
  {title:'Procedure and drafting record',text:record.events.map(e=>e.number+'. '+e.kind+': '+e.text).join('\n')||'No revisions recorded.'},
  {title:'Learning references',text:'WHO Basic Documents, 49th edition (2020), Constitution Articles 18–23 and 28; WHA Rules 69–73. Global Model WHO 2025 Simulation Handbook, printed pages 4–15: consultations, paragraph review, committee/plenary and drafting. ICONSnet: https://icons.umd.edu/about/iconsnet (accessed 25 October 2026). The handbook is an educational protocol; this prototype does not implement every formal WHO rule.'}
 ];}
 function coach(role,terms){const notes=[];if(!ready())notes.push('Some paragraphs remain open or bracketed. Ask what wording would remove the objection before seeking committee agreement.');if(!record.implementation.owner)notes.push('Who will carry out the recommendation? Specify a responsible institution rather than assuming the WHO will deliver every action.');if(!record.implementation.indicator)notes.push('What observable indicator would distinguish an adopted promise from implementation?');if(role==='n')notes.push('Nordland: offer a reporting timetable or review mechanism in exchange for predictable financing.');if(role==='k')notes.push('Kitala: compare the allocation with priority need, then distinguish the allocation gap from delivery losses.');if(role==='m')notes.push('Meridia: explain why purchase certainty changes your position; a recommendation alone is not a procurement contract.');if(role==='p')notes.push('Pelagia: ask whether delivery support is included in the financing total and who reaches remote communities.');if(role==='chair')notes.push('Chair: summarize both positions neutrally. Ask whether any objection remains; do not infer consent from silence on a shared screen.');if(terms?.supply)notes.push('Scenario check: '+terms.supply+'m courses available. Changes in percentages redistribute this pool; they do not create new supply.');return notes;}
 reset();return {reset,contribute,edit,ready,committee,invalidate,adopt,reservation,implementation,snapshot,reportSections,coach,log};
})();
if(typeof module!=='undefined')module.exports=Diplomacy;
